/**
 * CSS custom-property bridge for the design tokens.
 *
 * `tokens.css` (generated by `scripts/generate-tokens-css.ts` from
 * `renderTokensCss`) defines every color / elevation / motion token as a
 * variable on `[data-theme="light"]` / `[data-theme="dark"]`. Components then
 * compile `sx` against `CSS_VAR_COLORS`, whose values are `var(--ui-color-*)`
 * references, so switching scheme is a single attribute flip on the theme
 * root — no restyle pass through the tree.
 */

import { COLOR_PALETTE } from './colors/color-palette';
import type { ColorScheme, ColorTokenName, ColorTokens } from './colors/types';
import { duration, easing } from './motion';
import {
  borderRadius,
  type ElevationLevel,
  type ElevationStyle,
  fontSize,
  lineHeight,
  makeElevation,
  spacing,
} from './scale';

const COLOR_TOKEN_NAMES = Object.keys(COLOR_PALETTE.light) as ColorTokenName[];

function kebab(name: string): string {
  return name.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase());
}

/** `var(--ui-color-<token>)` for a palette token. */
export function colorVar(name: ColorTokenName): string {
  return `var(--ui-color-${kebab(name)})`;
}

/** Palette-shaped map whose values are CSS variable references. */
export const CSS_VAR_COLORS: ColorTokens = Object.fromEntries(
  COLOR_TOKEN_NAMES.map((name) => [name, colorVar(name)])
) as ColorTokens;

const ELEVATION_LEVELS: readonly ElevationLevel[] = [1, 2, 3, 4, 5];

/**
 * Scheme-agnostic elevation: level N lifts onto `var(--ui-elevation-N)`. Light
 * mode defines the variable as `transparent` (the host's own default), dark
 * mode as the matching surface tier.
 */
export function cssVarElevation(level: ElevationLevel): ElevationStyle {
  if (level === 0) return {};
  return { backgroundColor: `var(--ui-elevation-${level})` };
}

function schemeBlock(scheme: ColorScheme): string {
  const colors = COLOR_PALETTE[scheme];
  const elevation = makeElevation(colors, scheme);
  const lines: string[] = [];
  for (const name of COLOR_TOKEN_NAMES) {
    lines.push(`  --ui-color-${kebab(name)}: ${colors[name]};`);
  }
  for (const level of ELEVATION_LEVELS) {
    const bg = elevation(level).backgroundColor ?? 'transparent';
    lines.push(`  --ui-elevation-${level}: ${bg};`);
  }
  // Default on-color cascade for icons/text outside an OnColorProvider.
  lines.push('  --ui-on-fg: var(--ui-color-text);');
  lines.push('  --ui-on-fg-muted: var(--ui-color-text-secondary);');
  lines.push('  --ui-on-icon: var(--ui-color-icon);');
  lines.push(`  color-scheme: ${scheme};`);
  return `[data-theme="${scheme}"] {\n${lines.join('\n')}\n}`;
}

function scaleBlock(): string {
  const lines: string[] = [];
  for (const [key, value] of Object.entries(spacing)) {
    lines.push(`  --ui-space-${key.replace('.', '-')}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(fontSize)) {
    lines.push(`  --ui-font-size-${key}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(lineHeight)) {
    lines.push(`  --ui-line-height-${key}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(borderRadius)) {
    lines.push(`  --ui-radius-${key}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(duration)) {
    lines.push(`  --ui-duration-${key}: ${value}ms;`);
  }
  for (const [key, value] of Object.entries(easing)) {
    lines.push(`  --ui-easing-${key}: ${value};`);
  }
  return `:root {\n${lines.join('\n')}\n}`;
}

/** Full contents of `tokens.css`. Pure; the generator script writes it. */
export function renderTokensCss(): string {
  return [
    '/* GENERATED by pkgs/ui/scripts/generate-tokens-css.ts — do not edit. */',
    scaleBlock(),
    schemeBlock('light'),
    schemeBlock('dark'),
    '',
  ].join('\n\n');
}
